// Minimal sketch of per-page fault handling (pseudo-C)
typedef struct { int inflight; void* frame; int swapped; } Page;
void handle_fault(Page* p) {
  if (atomic_compare_and_swap(&p->inflight, 0, 1) == 0) {
    p->frame = allocate_frame();
    if (p->swapped) read_from_storage(p->frame);
    else zero_fill(p->frame);
    update_pte(p, p->frame);
    invalidate_tlb();
    wake_waiters(p);
    p->inflight = 0;
  } else {
    wait_for_completion(p);
  }
}
